CREATE TABLE "a" (
  "id" int PRIMARY KEY,
  "b_id" int NOT NULL,
  "n" int
);

CREATE TABLE "b" (
  "id" int PRIMARY KEY,
  "u" int UNIQUE
);

ALTER TABLE "b" ADD FOREIGN KEY ("id") REFERENCES "a" ("b_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "b" ADD CONSTRAINT "r2" FOREIGN KEY ("u") REFERENCES "a" ("n") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
